class Gradebook:
    def __init__(self) -> None:
        # assignment name -> (weight, kind)
        self._assignments = {}
        # student -> {assignment name: grade}
        self._grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError(f"Unknown assignment kind: {kind!r}")
        if name in self._assignments:
            raise ValueError(f"Assignment already exists: {name!r}")
        if weight < 0:
            raise ValueError("Weight must be non-negative")
        self._assignments[name] = (float(weight), kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment!r}")
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the scale 2.0-5.0")
        self._grades.setdefault(student, {})[assignment] = float(grade)

    def students(self) -> list[str]:
        return sorted(
            student for student, grades in self._grades.items() if grades
        )

    def grades(self, student: str) -> dict[str, float]:
        return dict(self._grades.get(student, {}))

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})

        # Determine drop target: lowest quiz grade if more than one quiz recorded.
        quiz_names = [
            name for name, (_, kind) in self._assignments.items() if kind == "quiz"
        ]
        recorded_quizzes = [q for q in quiz_names if q in student_grades]
        dropped_quiz = None
        if len(recorded_quizzes) > 1:
            dropped_quiz = min(recorded_quizzes, key=lambda q: student_grades[q])

        total_weight = 0.0
        weighted_sum = 0.0

        for name, (weight, _kind) in self._assignments.items():
            if name == dropped_quiz:
                continue
            grade = student_grades.get(name, 2.0)  # missing counts as 2.0
            weighted_sum += weight * grade
            total_weight += weight

        if total_weight == 0.0:
            return 0.0
        return round(weighted_sum / total_weight, 2)
```

